// intent: advance steadily while tapping fire, halting to shoot enemies in the way, hopping hazards even while halted, and pushing forward whenever progress stalls
const SOLID = '#cC><|';
function solid(c) { return SOLID.indexOf(c) >= 0; }
function bad(c) { return c === '^' || c === '~'; }
function footing(obs, dx) {
  for (let dy = 1; dy <= 5; dy++) {
    const c = obs.tile(dx, dy);
    if (bad(c)) return -1;
    if (solid(c) || c === '=') return dy;
  }
  return 0;
}

function control(obs, mem) {
  const me = obs.me;
  const out = {};
  let dir = 1;

  if (mem.best === undefined) { mem.best = me.x; mem.since = 0; mem.free = 0; }
  if (obs.inArena || me.x > mem.best + 2) { mem.best = me.x; mem.since = 0; } else mem.since++;
  if (mem.since > 120) { mem.free = 40; mem.since = 0; }
  const forced = mem.free > 0;
  if (forced) mem.free--;

  // Nearest thing worth shooting (flamers cannot be killed).
  let target = null;
  for (const e of obs.enemies) {
    if (e.kind === 'flamer') continue;
    if (Math.abs(e.dy) < 40 && Math.abs(e.dx) < 200) { target = e; break; }
  }
  if (obs.boss) target = obs.boss;

  if (target && !forced) {
    const face = target.dx >= 0 ? 1 : -1;
    const range = obs.boss ? 110 : 90;
    if (Math.abs(target.dx) > range) dir = face;          // close in
    else if (Math.abs(target.dx) < range - 40) dir = -face; // too close: back off
    else dir = 0;
    // Must be facing it to hit it: a one-frame tap turns us round.
    if (dir === 0 && me.facing !== face) dir = face;
  }
  if (dir > 0) out.right = true;
  if (dir < 0) out.left = true;

  // Tap fire: press 4 frames, release 4.
  out.fire = (obs.t % 8) < 4;

  if (mem.hold > 0) { mem.hold--; out.jump = true; }
  const ahead = dir || me.facing;
  const wall = solid(obs.tile(ahead, 0)) || solid(obs.tile(ahead, -1));
  const f1 = footing(obs, ahead), f2 = footing(obs, 2 * ahead);
  const danger = f1 <= 0 || f2 < 0 || bad(obs.tile(ahead, 0));
  const incoming = obs.shots.some(s => Math.abs(s.dy) < 16 && Math.abs(s.dx) < 50 && s.dx * s.vx < 0);
  if (me.ground && !mem.prev && (wall || danger || incoming)) { mem.hold = 16; out.jump = true; }
  if (!me.ground && me.wall !== 0 && me.vy > 0 && !mem.prev) { mem.hold = 10; out.jump = true; }

  mem.prev = !!out.jump;
  return out;
}

// intent: run right with deterministic full jumps over pits, walls, hazards and enemies, air-dash gaps, fire only a rare single shot in levels, and shoot the boss at a moderate rate while facing it
const SOLID = '#cC><|';
function solid(c) { return SOLID.indexOf(c) >= 0; }
function bad(c) { return c === '^' || c === '~'; }

function footing(obs, dx) {
  for (let dy = 1; dy <= 5; dy++) {
    const c = obs.tile(dx, dy);
    if (bad(c)) return -1;
    if (solid(c) || c === '=') return dy;
  }
  return 0;
}

function gapWidth(obs) {
  let w = 0;
  for (let dx = 1; dx <= 8; dx++) {
    if (footing(obs, dx) > 0) break;
    w++;
  }
  return w;
}

function control(obs, mem) {
  const me = obs.me;
  const out = { right: true };
  if (mem.best === undefined) {
    mem.best = me.x; mem.since = 0; mem.back = 0;
    mem.hold = 0; mem.cool = 0;
  }
  if (me.x > mem.best + 2) { mem.best = me.x; mem.since = 0; } else mem.since++;

  if (!obs.inArena) {
    if (mem.since > 100 && mem.back <= 0) { mem.back = 18; mem.since = 0; }
    if (mem.back > 0) { mem.back--; out.right = false; out.left = true; }
  }

  const wall = solid(obs.tile(1, 0)) || solid(obs.tile(1, -1));
  const f1 = footing(obs, 1), f2 = footing(obs, 2), f3 = footing(obs, 3);
  const hz = bad(obs.tile(1, 0)) || bad(obs.tile(2, 0)) || bad(obs.tile(3, 0)) || f2 < 0 || f3 < 0;
  const near = obs.enemies.some(e => e.kind !== 'flamer'
    ? (e.dx > 0 && e.dx < 45 && Math.abs(e.dy) < 30)
    : (e.dx > 0 && e.dx < 45));
  const incoming = obs.shots.some(s => Math.abs(s.dy) < 16 && Math.abs(s.dx) < 40 && s.dx * s.vx < 0 && s.warn <= 0);

  if (mem.cool > 0) mem.cool--;
  if (mem.hold > 0) {
    mem.hold--;
    out.jump = true;
    if (mem.hold === 0) mem.cool = 2;
  } else if (me.ground && mem.cool <= 0) {
    if (f1 <= 0) {
      mem.hold = 32; out.jump = true;
    } else if (wall) {
      mem.hold = 22; out.jump = true;
    } else if (hz) {
      mem.hold = 24; out.jump = true;
    } else if (near || incoming) {
      mem.hold = 14 + (obs.t % 3); out.jump = true;
    }
  } else if (!me.ground && me.wall !== 0 && me.vy > 0 && mem.cool <= 0) {
    mem.hold = 10; out.jump = true;
  }

  if (!me.ground && me.vy > -2 && gapWidth(obs) >= 2 && me.dashReady && !mem.back) {
    out.dash = true; out.right = true; out.left = false;
  }

  // small input variety when the way is clear
  if (me.ground && !mem.hold && !mem.back && f1 > 0 && f2 > 0 && f3 > 0 && !hz && !wall && !near && Math.random() < 0.03) {
    out.right = false;
  }

  if (obs.inArena) {
    const b = obs.boss;
    const facingBoss = !b || (b.dx >= 0 ? me.facing > 0 : me.facing < 0);
    out.fire = facingBoss && (obs.t % 16) < 4;
  } else {
    out.fire = (obs.t % 180) < 2;
  }

  if (obs.boss && obs.boss.dx > 0 && obs.boss.dx < 60) { out.right = false; out.left = true; }
  return out;
}

// intent: hold right constantly, hopping when a wall, spike, gap or nearby enemy is ahead, air-dashing across wide gaps, and backing off briefly when stuck
function solid(c) { return '#cC><|'.indexOf(c) >= 0; }
function hasGround(obs, dx) {
  for (let dy = 1; dy <= 4; dy++) {
    const c = obs.tile(dx, dy);
    if (solid(c) || c === '=') return true;
  }
  return false;
}
function hazard(obs, dx) {
  for (let dy = 0; dy <= 1; dy++) {
    const c = obs.tile(dx, dy);
    if (c === '^' || c === '~') return true;
  }
  return false;
}

function control(obs, mem) {
  const me = obs.me;
  const out = { right: true };
  if (mem.best === undefined) { mem.best = me.x; mem.since = 0; mem.back = 0; mem.hold = 0; mem.prev = false; }
  if (me.x > mem.best + 2) { mem.best = me.x; mem.since = 0; } else mem.since++;

  // Stuck for a few seconds: back up briefly, then go again.
  if (mem.since > 240 && mem.back <= 0) { mem.back = 30; mem.since = 0; }
  if (mem.back > 0) { mem.back--; out.right = false; out.left = true; }

  const wall = solid(obs.tile(1, 0)) || solid(obs.tile(1, -1));
  const gap = !hasGround(obs, 1);
  const spikes = hazard(obs, 1) || hazard(obs, 2);
  const foe = obs.enemies.some(e => e.dx > 14 && e.dx < 44 && e.dy > -28 && e.dy < 12);

  const under = obs.tile(0, 1);
  const crumb = under === 'c' || under === 'C';
  let want = me.ground && (wall || gap || spikes || foe || (crumb && !hasGround(obs, 2)));
  // Clinging to a wall while falling: kick off it.
  if (!me.ground && me.wall !== 0 && me.vy > 0) want = true;

  // Hold jump for a fixed span; a new press needs a released frame first.
  if (mem.hold > 0) { mem.hold--; out.jump = true; }
  else if (want && !mem.prev) { mem.hold = gap ? 32 : 20; out.jump = true; }

  // Airborne near the apex with a gap 2-4 tiles ahead: dash now so the 80 px burst reaches the far side.
  const gapAhead = !hasGround(obs, 2) || !hasGround(obs, 3) || !hasGround(obs, 4) || !hasGround(obs, 5);
  const blocked = solid(obs.tile(2, -1)) || solid(obs.tile(3, -1)) || solid(obs.tile(2, -2)) || solid(obs.tile(3, -2));
  const lands = hasGround(obs, 6) || hasGround(obs, 7) || hasGround(obs, 8);
  if (!me.ground && me.vy > -2 && me.dashReady && !me.dashing && gapAhead && lands && !blocked && mem.back <= 0) {
    out.dash = true; out.right = true; out.left = false;
  }

  mem.prev = !!out.jump;
  return out;
}

// intent: run right with full-height jumps timed over every gap, pit and hazard, air-dash across gaps, wall kicks, and jittered stutters only on clear ground, firing tap shots in levels and rapid tap at the boss while facing it
const SOLID = '#cC><|';
function solid(c) { return SOLID.indexOf(c) >= 0; }
function bad(c) { return c === '^' || c === '~'; }

// Depth of footing in column dx: 1..5 if solid ground, -1 if a hazard comes first, 0 if none.
function footing(obs, dx) {
  for (let dy = 1; dy <= 5; dy++) {
    const c = obs.tile(dx, dy);
    if (bad(c)) return -1;
    if (solid(c) || c === '=') return dy;
  }
  return 0;
}

function gapWidth(obs) {
  let w = 0;
  for (let dx = 1; dx <= 8; dx++) {
    if (footing(obs, dx) > 0) break;
    w++;
  }
  return w;
}

function control(obs, mem) {
  const me = obs.me;
  const out = { right: true };
  if (mem.best === undefined) {
    mem.best = me.x; mem.since = 0; mem.back = 0;
    mem.hold = 0; mem.cool = 0; mem.f = 0; mem.stut = 0;
  }
  if (me.x > mem.best + 2) { mem.best = me.x; mem.since = 0; } else mem.since++;

  if (!obs.inArena) {
    if (mem.since > 100 && mem.back <= 0) { mem.back = 18; mem.since = 0; }
    if (mem.back > 0) { mem.back--; out.right = false; out.left = true; }
  }

  const wall = solid(obs.tile(1, 0)) || solid(obs.tile(1, -1));
  const f1 = footing(obs, 1), f2 = footing(obs, 2), f3 = footing(obs, 3);
  const hz = bad(obs.tile(1, 0)) || bad(obs.tile(2, 0)) || bad(obs.tile(3, 0)) || f2 < 0 || f3 < 0;
  const danger = f1 <= 0 || hz;
  const clear = [2, 3, 4, 5, 6].every(d => footing(obs, d) > 0);
  const near = obs.enemies.some(e => e.kind !== 'flamer'
    ? (e.dx > 0 && e.dx < 45 && Math.abs(e.dy) < 30)
    : (e.dx > 0 && e.dx < 45));
  const incoming = obs.shots.some(s => Math.abs(s.dy) < 16 && Math.abs(s.dx) < 40 && s.dx * s.vx < 0 && s.warn <= 0);

  // Jumps: full-height jumps over hazards; jitter only where ground is clear.
  if (mem.cool > 0) mem.cool--;
  if (mem.hold > 0) {
    mem.hold--;
    out.jump = true;
    if (mem.hold === 0) mem.cool = 2;
  } else if (me.ground && mem.cool <= 0) {
    if (f1 <= 0) {
      mem.hold = 30; out.jump = true;
    } else if (wall) {
      mem.hold = 22; out.jump = true;
    } else if (hz) {
      mem.hold = 24; out.jump = true;
    } else if (near || incoming) {
      mem.hold = 14 + (obs.t % 3); out.jump = true;
    } else if (clear && Math.random() < 0.04) {
      mem.hold = 14 + Math.floor(Math.random() * 8); out.jump = true;
    }
  } else if (!me.ground && me.wall !== 0 && me.vy > 0 && mem.cool <= 0) {
    mem.hold = 10; out.jump = true;
  }

  // Input variety: short stutters only when no gap lies within six tiles.
  if (me.ground && clear && !danger && !wall && mem.stut <= 0 && Math.random() < 0.1) {
    mem.stut = 3 + Math.floor(Math.random() * 6);
  }
  if (mem.stut > 0 && (!me.ground || !clear || danger || wall || mem.hold > 0)) mem.stut = 0;
  if (mem.stut > 0) {
    mem.stut--;
    out.right = false;
    if (Math.random() < 0.25) out.left = true;
  }

  // Air dash across gaps.
  if (!me.ground && me.vy > -2 && gapWidth(obs) >= 2 && me.dashReady && !mem.back) {
    out.dash = true; out.right = true; out.left = false;
  }

  // Fire: rapid tap at the boss while facing it; steady taps in levels.
  if (obs.inArena) {
    const b = obs.boss;
    const facingBoss = !b || (b.dx >= 0 ? me.facing > 0 : me.facing < 0);
    out.fire = facingBoss && (obs.t % 8) < 4;
  } else if (mem.f <= 0) {
    out.fire = true;
    mem.f = 22 + Math.floor(Math.random() * 6);
  } else {
    mem.f--;
  }

  if (obs.boss && obs.boss.dx > 0 && obs.boss.dx < 60) { out.right = false; out.left = true; }
  return out;
}

// intent: run right with full jumps over pits, walls and hazards, tap moderate shots in levels, and in boss fights hold a mid distance facing the boss, rapid-fire and hop over incoming shots
const SOLID = '#cC><|';
function solid(c) { return SOLID.indexOf(c) >= 0; }
function bad(c) { return c === '^' || c === '~'; }

function footing(obs, dx) {
  for (let dy = 1; dy <= 5; dy++) {
    const c = obs.tile(dx, dy);
    if (bad(c)) return -1;
    if (solid(c) || c === '=') return dy;
  }
  return 0;
}

function gapWidth(obs) {
  let w = 0;
  for (let dx = 1; dx <= 8; dx++) {
    if (footing(obs, dx) > 0) break;
    w++;
  }
  return w;
}

function control(obs, mem) {
  const me = obs.me;
  const out = { right: true };
  if (mem.best === undefined) {
    mem.best = me.x; mem.since = 0; mem.back = 0;
    mem.hold = 0; mem.cool = 0;
  }
  if (me.x > mem.best + 2) { mem.best = me.x; mem.since = 0; } else mem.since++;

  const arena = obs.inArena;
  if (!arena) {
    if (mem.since > 100 && mem.back <= 0) { mem.back = 18; mem.since = 0; }
    if (mem.back > 0) { mem.back--; out.right = false; out.left = true; }
  }

  const wall = solid(obs.tile(1, 0)) || solid(obs.tile(1, -1));
  const f1 = footing(obs, 1), f2 = footing(obs, 2), f3 = footing(obs, 3);
  const hz = bad(obs.tile(1, 0)) || bad(obs.tile(2, 0)) || bad(obs.tile(3, 0)) || f2 < 0 || f3 < 0;
  const near = obs.enemies.some(e => e.kind !== 'flamer'
    ? (e.dx > 0 && e.dx < 45 && Math.abs(e.dy) < 30)
    : (e.dx > 0 && e.dx < 45));
  const incoming = obs.shots.some(s => Math.abs(s.dy) < 16 && Math.abs(s.dx) < (arena ? 70 : 40) && s.dx * s.vx < 0 && s.warn <= 0);

  if (mem.cool > 0) mem.cool--;
  if (mem.hold > 0) {
    mem.hold--;
    out.jump = true;
    if (mem.hold === 0) mem.cool = 2;
  } else if (me.ground && mem.cool <= 0) {
    if (arena) {
      if (incoming || near) { mem.hold = 16 + (obs.t % 3); out.jump = true; }
    } else if (f1 <= 0) {
      mem.hold = 32; out.jump = true;
    } else if (wall) {
      mem.hold = 22; out.jump = true;
    } else if (hz) {
      mem.hold = 24; out.jump = true;
    } else if (near || incoming) {
      mem.hold = 14 + (obs.t % 3); out.jump = true;
    }
  } else if (!arena && !me.ground && me.wall !== 0 && me.vy > 0 && mem.cool <= 0) {
    mem.hold = 10; out.jump = true;
  }

  if (!arena && !me.ground && me.vy > -2 && gapWidth(obs) >= 2 && me.dashReady && !mem.back) {
    out.dash = true; out.right = true; out.left = false;
  }

  if (arena) {
    const b = obs.boss;
    out.right = false; out.left = false;
    let facingBoss = true;
    if (b) {
      const tw = b.dx >= 0 ? 1 : -1;
      const dist = Math.abs(b.dx);
      facingBoss = me.facing === tw;
      let dir = 0;
      if (dist < 70) dir = -tw;
      else if (dist > 110) dir = tw;
      else if (!facingBoss) dir = tw;
      if (dir > 0) out.right = true;
      if (dir < 0) out.left = true;
    }
    out.fire = facingBoss && (obs.t % 8) < 4;
  } else {
    out.fire = (obs.t % 60) < 3;
  }
  return out;
}

// intent: run right with randomly varied hops, wall kicks and brief stutters, firing a tap about every second or two at what is ahead
const SOLID = '#cC><|';
function solid(c) { return SOLID.indexOf(c) >= 0; }
function bad(c) { return c === '^' || c === '~'; }

function footing(obs, dx) {
  for (let dy = 1; dy <= 5; dy++) {
    const c = obs.tile(dx, dy);
    if (bad(c)) return -1;
    if (solid(c) || c === '=') return dy;
  }
  return 0;
}

function gapWidth(obs) {
  let w = 0;
  for (let dx = 1; dx <= 8; dx++) {
    if (footing(obs, dx) > 0) break;
    w++;
  }
  return w;
}

function gapAhead(obs, k) {
  for (let dx = 1; dx <= k; dx++) {
    if (footing(obs, dx) <= 0 || bad(obs.tile(dx, 0))) return true;
  }
  return false;
}

function control(obs, mem) {
  const me = obs.me;
  const out = { right: true };
  if (mem.best === undefined) {
    mem.best = me.x; mem.since = 0; mem.back = 0;
    mem.hold = 0; mem.cool = 0; mem.nf = 30;
  }
  if (me.x > mem.best + 2) { mem.best = me.x; mem.since = 0; } else mem.since++;

  if (!obs.inArena) {
    if (mem.since > 80 && mem.back <= 0) { mem.back = 20; mem.since = 0; }
    if (mem.back > 0) { mem.back--; out.right = false; out.left = true; }
  }

  const wall = solid(obs.tile(1, 0)) || solid(obs.tile(1, -1));
  const f1 = footing(obs, 1), f2 = footing(obs, 2);
  const danger = f1 <= 0 || f2 < 0 || bad(obs.tile(1, 0));
  const near = obs.enemies.some(e => e.dx > 0 && e.dx < 55 && Math.abs(e.dy) < 30 && e.kind !== 'flamer' ? true : (e.kind === 'flamer' && e.dx > 0 && e.dx < 40));

  if (mem.cool > 0) mem.cool--;
  if (mem.hold > 0) {
    mem.hold--;
    out.jump = true;
    if (mem.hold === 0) mem.cool = 2;
  } else if (me.ground && mem.cool <= 0) {
    if (f1 <= 0) {
      mem.hold = 32; out.jump = true;
      if (me.dashReady && !mem.back) out.dash = true;
    } else if (wall || danger) {
      mem.hold = 20; out.jump = true;
    } else if (gapAhead(obs, 2) && me.dashReady && !mem.back) {
      mem.hold = 24; out.jump = true; out.dash = true;
    } else if (!gapAhead(obs, 7) && (near || Math.random() < 0.035)) {
      mem.hold = 7 + Math.floor(Math.random() * 10); out.jump = true;
    }
  } else if (!me.ground && me.wall !== 0 && me.vy > 0 && mem.cool <= 0) {
    mem.hold = 10; out.jump = true;
  }

  if (!me.ground && me.vy > -2 && gapWidth(obs) >= 2 && me.dashReady) out.dash = true;

  // Input variety: brief stutters when it is safe.
  if (me.ground && !danger && !wall && f1 > 0 && Math.random() < 0.08) {
    out.right = false;
    if (Math.random() < 0.3) out.left = true;
  }

  // Sparse tap fire, a bit faster when something is lined up ahead.
  if (obs.t >= mem.nf) {
    out.fire = true;
    const lined = obs.enemies.some(e => e.dx > 0 && e.dx < 180 && Math.abs(e.dy) < 24);
    const base = obs.inArena ? 35 : (lined ? 45 : 80);
    mem.nf = obs.t + base + Math.random() * 40;
  }

  if (obs.boss && obs.boss.dx > 0 && obs.boss.dx < 60) { out.right = false; out.left = true; }
  return out;
}

// intent: run steadily right while tapping fire on a fixed 18-frame rhythm, hopping early over walls, spikes, liquid and gaps, and air-dashing across any gap ahead near the apex of the hop
const SOLID = '#cC><|';
function solid(c) { return SOLID.indexOf(c) >= 0; }
function hard(c) { return c === '^' || c === '~'; }
// Is there ground under the column dx, within 4 tiles below the feet?
function floorAt(obs, dx) {
  for (let dy = 1; dy <= 4; dy++) {
    const c = obs.tile(dx, dy);
    if (c === '~' || c === '^') return false;
    if (solid(c) || c === '=') return true;
  }
  return false;
}

function control(obs, mem) {
  const me = obs.me;
  // Fixed rhythm: fire 9 frames on, 9 off (about 3.3 shots/s).
  const out = { right: true, fire: (obs.t % 18) < 9 };
  const cool = mem.cool || 0;
  mem.cool = cool > 0 ? cool - 1 : 0;
  if (mem.hold > 0) { mem.hold--; out.jump = true; }
  // Air dash across any gap within 5 tiles ahead.
  const ahead = [1, 2, 3, 4].some(d => !floorAt(obs, d));
  if (!me.ground && ahead && me.vy > -2 && me.dashReady) out.dash = true;
  if (cool > 0) return out;
  let go = false;
  if (me.ground) {
    const wall = solid(obs.tile(1, 0)) || solid(obs.tile(1, -1)) || hard(obs.tile(1, 0)) || hard(obs.tile(2, 0));
    const gap = !floorAt(obs, 1) || !floorAt(obs, 2) || !floorAt(obs, 3) || !floorAt(obs, 4);
    go = wall || gap;
    if (gap && !wall) mem.hold = 20;
  } else if (me.wall !== 0 && me.vy > 0) {
    // Clinging to a wall while falling: kick off it.
    go = true;
  }
  if (go) { out.jump = true; mem.cool = 20; }
  return out;
}

// intent: bunny-hop right with randomised hop and rest lengths, take off long from pits and hazards ahead, air-dash wide gaps, and tap one shot about every 0.7 seconds
const SOLID = '#cC><|';
function solid(c) { return SOLID.indexOf(c) >= 0; }
function bad(c) { return c === '^' || c === '~'; }

// Solid floor under column dx within 5 tiles below feet, with no spikes or liquid right under the feet.
function floorAt(obs, dx) {
  for (let dy = 1; dy <= 5; dy++) {
    const c = obs.tile(dx, dy);
    if (dy <= 2 && bad(c)) return false;
    if (solid(c) || c === '=') return true;
  }
  return false;
}

// Number of floorless columns ahead before solid footing.
function gapWidth(obs) {
  let w = 0;
  for (let dx = 1; dx <= 8 && !floorAt(obs, dx); dx++) w++;
  return w;
}

function hazard(obs) {
  for (let dx = 1; dx <= 3; dx++) {
    if (bad(obs.tile(dx, 0)) || bad(obs.tile(dx, 1))) return true;
  }
  return false;
}

function control(obs, mem) {
  const me = obs.me;
  const out = { right: true };

  if (mem.h === undefined) { mem.h = 12; mem.r = 2; mem.c = 0; }
  mem.c++;

  const gap = gapWidth(obs);
